{
  "name": "@ephemushroom/opencode-claude-mem",
  "version": "0.7.1",
  "description": "Claude-Mem for OpenCode: capture through the official claude-mem plugin, memory tools and the Memory sidebar in one package",
  "type": "module",
  "files": [
    "dist"
  ],
  "exports": {
    "./server": {
      "types": "./dist/server.d.ts",
      "import": "./dist/server.js"
    },
    "./tui": {
      "types": "./dist/package-tui.d.ts",
      "import": "./dist/package-tui.js"
    },
    "./cli": {
      "types": "./dist/cli.d.ts",
      "import": "./dist/cli.js"
    }
  },
  "scripts": {
    "build": "bun build src/server.ts --outfile dist/server.js --target bun --format esm && bun build src/tui.ts --outfile dist/tui.js --target bun --format esm --external @opentui/solid --external solid-js && bun build src/cli.ts --outfile dist/cli.js --target bun --format esm --external @opentui/solid --external solid-js && bun src/build-tui-bridge.ts && tsc -p tsconfig.build.json --emitDeclarationOnly",
    "dev": "tsc --watch",
    "clean": "rm -rf dist",
    "lint": "oxlint",
    "fmt": "oxfmt --write src/",
    "fmt:check": "oxfmt --check src/",
    "typecheck": "tsc --noEmit",
    "prepublishOnly": "bun run clean && bun run build"
  },
  "keywords": [
    "opencode",
    "claude-mem",
    "memory",
    "plugin",
    "persistent-memory"
  ],
  "author": "",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Ephemushroom/opencode-claude-mem.git"
  },
  "bugs": {
    "url": "https://github.com/Ephemushroom/opencode-claude-mem/issues"
  },
  "homepage": "https://github.com/Ephemushroom/opencode-claude-mem#readme",
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@opentui/solid": "0.8.1"
  },
  "devDependencies": {
    "@opencode/plugin": "2.2.7",
    "@opencode/theme": "2.2.7",
    "@opentui/core": "0.8.1",
    "@types/bun": "latest",
    "oxfmt": "^0.33.0",
    "oxlint": "^1.63.0",
    "solid-js": "1.9.17",
    "typescript": "^5.9.3",
    "zod": "4.1.8"
  }
}
